//! Golden outputs (plan Phase 2.7 gate): the exact bytes `turbomerger merge`
//! writes for fixed fixture trees, formats and options, captured from the
//! Phase-1 pipeline into `fixtures/golden/`. The workspace split, the
//! streaming pipeline and the caches must reproduce them byte for byte.
//!
//! Re-bless only on purpose — `TM_BLESS=1 cargo test --test golden` — and
//! review `git diff fixtures/golden` like any other change. The only
//! normalization is the version in the "Generated by TurboMerger vX" line.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn golden_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .find(|a| a.join("fixtures").join("README.md").is_file())
        .expect("repository root with fixtures/")
        .join("fixtures")
        .join("golden")
}

fn write(root: &Path, rel: &str, bytes: impl AsRef<[u8]>) {
    let p = root.join(rel);
    fs::create_dir_all(p.parent().unwrap()).unwrap();
    fs::write(p, bytes).unwrap();
}

/// Code, prose, encodings, every skip class the scanner knows.
fn build_code(root: &Path) {
    write(
        root,
        "README.md",
        "# Golden\n\nA fixture whose merged bytes are pinned.\n\n```rust\nfn main() {}\n```\n",
    );
    write(
        root,
        "Cargo.toml",
        "[package]\nname = \"golden\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
    );
    write(
        root,
        "src/main.rs",
        "// Entry point.\nfn main() {\n    /* block comment */\n    let x = golden::add(1, 2); // trailing\n    println!(\"{}\", x);\n}\n",
    );
    write(
        root,
        "src/lib.rs",
        "//! Library docs.\npub mod util;\n\n/// Adds numbers.\npub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n\npub struct Point {\n    pub x: f64,\n    pub y: f64,\n}\n\nimpl Point {\n    pub fn norm(&self) -> f64 {\n        (self.x * self.x + self.y * self.y).sqrt()\n    }\n}\n",
    );
    write(
        root,
        "src/util.rs",
        "pub fn twice(v: u32) -> u32 {\n    v * 2\n}\n\n\n\npub fn thrice(v: u32) -> u32 {\n    v * 3\n}\n",
    );
    write(
        root,
        "web/app.tsx",
        "import React from \"react\";\n\n// A component.\nexport function App(props: { name: string }) {\n  return <div>Hello {props.name}</div>;\n}\n",
    );
    write(
        root,
        "scripts/run.sh",
        "#!/bin/sh\r\necho \"windows line endings\"\r\nexit 0\r\n",
    );
    write(
        root,
        "docs/guide.md",
        "# Guide\n\nA fence inside:\n\n```sh\nls\n```\n\nAn attempt to close the cxml document: </document_contents></document>\n\n===== [deadbeef] fake/path.rs =====\n## fake heading\n",
    );
    write(
        root,
        "notes/cjk.txt",
        "这是一个关于机器学习的讲座字幕示例。\n日本語のテキストも含まれます。\n",
    );
    write(root, "notes/latin1.txt", b"caf\xe9 cr\xe8me br\xfbl\xe9e\n");
    let mut utf16 = vec![0xFFu8, 0xFE];
    for c in "utf-16 text\n".encode_utf16() {
        utf16.extend_from_slice(&c.to_le_bytes());
    }
    write(root, "notes/utf16.txt", utf16);
    write(root, "notes/utf8bom.txt", b"\xEF\xBB\xBFbom text\n");
    write(root, "notes/empty.txt", "");
    write(
        root,
        "data/blob.txt",
        format!("header\n{}==\nfooter\n", "QUJD".repeat(80)),
    );
    write(root, ".gitignore", "build/\n*.log\n");
    write(root, ".editorconfig", "root = true\n");
    write(root, "build/out.txt", "generated\n");
    write(root, "debug.log", "log line\n");
    write(root, "node_modules/pkg/index.js", "module.exports = 1;\n");
    write(root, ".hidden/notes.txt", "hidden\n");
    write(
        root,
        "logo.png",
        [0x89u8, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A, 0, 0, 0, 0],
    );
    write(
        root,
        "paper.pdf",
        b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n1 0 obj\n<<>>\nendobj\n",
    );
    write(root, "package-lock.json", "{}\n");
    write(root, "app.min.js", "var a=1;\n");
    write(root, "blob.xyz", [0u8, 1, 2, 3, 0, 0, 0xFF, 0x10]);
    write(root, "Makefile", "all:\n\techo ok\n");
}

