/// Eight ~1.2k-token files and one larger than a whole 3,000-token part.
fn build_split(root: &Path) {
    for i in 0..8 {
        let body: String = (0..60)
            .map(|j| format!("fn f{i}_{j}() {{ let v = {j} * 3 + 1; println!(\"{{}}\", v); }}\n"))
            .collect();
        write(root, &format!("src/f{i}.rs"), body);
    }
    let big: String = (0..220)
        .map(|j| format!("pub const C{j}: &str = \"line {j} of a file larger than one part\";\n"))
        .collect();
    write(root, "src/zz_big.rs", big);
    write(
        root,
        "README.md",
        "# Split\n\nParts under a 3,000-token budget.\n",
    );
}

/// Names and links only Unix file systems allow.
#[cfg(unix)]
fn build_unix(root: &Path) {
    use std::os::unix::fs::symlink;
    write(root, "src/a.rs", "pub fn a() {}\n");
    write(root, "src/dir/b.rs", "pub fn b() {}\n");
    write(root, "odd\nname.txt", "newline in the name\n");
    write(root, "tab\tname.txt", "tab in the name\n");
    write(root, "cafe\u{301}.txt", "NFD name\n");
    let outside = root.parent().unwrap().join("outside.txt");
    fs::write(&outside, "outside the root\n").unwrap();
    symlink("src/a.rs", root.join("link_to_a.rs")).unwrap();
    symlink("src/dir", root.join("link_dir")).unwrap();
    symlink(&outside, root.join("outside_link")).unwrap();
    symlink("missing.rs", root.join("broken_link")).unwrap();
}

