/// Run one merge; every file it wrote plus `_run.txt` (exit code and the
/// summary line), version-normalized.
fn run(run: &Run, src: &Path, work: &Path) -> BTreeMap<String, Vec<u8>> {
    let out_dir = work.join(format!("out_{}", run.name));
    fs::create_dir_all(&out_dir).unwrap();
    let out = out_dir.join(format!("{}.{}", run.name, run.ext));
    let o = Command::new(env!("CARGO_BIN_EXE_turbomerger"))
        .arg("merge")
        .arg(src)
        .arg(&out)
        .args(run.args)
        .current_dir(work)
        .env_remove("DISPLAY")
        .env_remove("WAYLAND_DISPLAY")
        .env("TURBOMERGER_STATE_DIR", work.join("state"))
        .output()
        .expect("binary runs");
    let version = format!("TurboMerger v{}", env!("CARGO_PKG_VERSION"));
    let normalize = |bytes: Vec<u8>| -> Vec<u8> {
        match String::from_utf8(bytes) {
            Ok(s) => s
                .replace(&version, "TurboMerger v0.0.0-golden")
                .into_bytes(),
            Err(e) => e.into_bytes(),
        }
    };
    let mut files = BTreeMap::new();
    for e in fs::read_dir(&out_dir).unwrap().flatten() {
        let name = e.file_name().to_string_lossy().into_owned();
        files.insert(name, normalize(fs::read(e.path()).unwrap()));
    }
    let stdout = String::from_utf8_lossy(&o.stdout);
    let summary = stdout.lines().next().unwrap_or("");
    files.insert(
        "_run.txt".to_string(),
        format!("exit={}\n{}\n", o.status.code().unwrap_or(-1), summary).into_bytes(),
    );
    files
}

fn first_difference(a: &[u8], b: &[u8]) -> String {
    let (a, b) = (String::from_utf8_lossy(a), String::from_utf8_lossy(b));
    for (i, (la, lb)) in a.lines().zip(b.lines()).enumerate() {
        if la != lb {
            return format!("line {}:\n  golden: {:?}\n  actual: {:?}", i + 1, la, lb);
        }
    }
    format!(
        "one is a prefix of the other ({} vs {} lines)",
        a.lines().count(),
        b.lines().count()
    )
}

#[test]
fn merge_outputs_match_the_golden_files() {
    let tmp = tempfile::tempdir().unwrap();
    let work = tmp.path();
    let builders: &[(&str, fn(&Path))] = &[
        ("golden_code", build_code),
        ("golden_secrets", build_secrets),
        ("golden_split", build_split),
        #[cfg(unix)]
        ("golden_unix", build_unix),
    ];
    for (name, build) in builders {
        let dir = work.join("src").join(name);
        fs::create_dir_all(&dir).unwrap();
        build(&dir);
    }

    let bless = std::env::var_os("TM_BLESS").is_some();
    let golden = golden_root();
    let mut failures = Vec::new();
    for r in RUNS {
        let actual = run(r, &work.join("src").join(r.fixture), work);
        let dir = golden.join(r.name);
        if bless {
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).unwrap();
            for (name, bytes) in &actual {
                fs::write(dir.join(name), bytes).unwrap();
            }
            continue;
        }
        let expected: BTreeMap<String, Vec<u8>> = match fs::read_dir(&dir) {
            Ok(rd) => rd
                .flatten()
                .map(|e| {
                    (
                        e.file_name().to_string_lossy().into_owned(),
                        fs::read(e.path()).unwrap(),
                    )
                })
                .collect(),
            Err(_) => {
                failures.push(format!(
                    "{}: no golden files (bless with TM_BLESS=1)",
                    r.name
                ));
                continue;
            }
        };
        let names: Vec<&String> = expected.keys().collect();
        let got: Vec<&String> = actual.keys().collect();
        if names != got {
            failures.push(format!(
                "{}: files differ: golden {:?}, actual {:?}",
                r.name, names, got
            ));
            continue;
        }
        for (name, bytes) in &expected {
            if &actual[name] != bytes {
                failures.push(format!(
                    "{}/{}: {}",
                    r.name,
                    name,
                    first_difference(bytes, &actual[name])
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "golden mismatches:\n{}",
        failures.join("\n")
    );
}
